<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue'
import {asset} from '../lib/assets'
import {api,apiBaseUrl,post} from '../lib/api'
import SettingsFlow from './SettingsFlow.vue'
import MomentsFlow from './MomentsFlow.vue'
import {tr, t} from '../lib/i18n'
import ChatFlow from './ChatFlow.vue'
const props=defineProps<{token:string;person?:{id:string;peerId?:string;displayName:string;avatar?:string;status:string;following?:boolean;city?:string;age?:number;zodiac?:string;bio?:string;cards?:string[];moments?:{id:string;text:string;src:string}[]}}>()
const emit=defineEmits<{close:[];security:[];inbox:[];chat:[];safety:[action:'report'|'block']}>()
type Photo={id:string;src:string;position:number}
type ServerProfile={id:string;displayName:string;age:number|null;city:string|null;zodiac:string|null;bio:string;avatar:string|null;avatars:{mediaId:string;url:string;position:number}[];recentlyRemoved?:{mediaId:string;url:string;position:number}[];following:boolean;permissions:{canFollow:boolean;conversationId:string|null}}
const initial={name:'',age:'' as number|string,city:'',zodiac:'',bio:'',slots:Array(8).fill(null) as (Photo|null)[],selected:'',archive:[] as Photo[],cards:[] as string[]}
const profile=ref(initial),publicProfile=ref<ServerProfile>(),publicAvatar=ref(''),publicCards=ref<string[]>([]),publicMoments=ref<{id:string;text:string;src:string}[]>([])
const headers={Authorization:`Bearer ${props.token}`},urls:string[]=[]
onUnmounted(()=>urls.forEach(url=>URL.revokeObjectURL(url)))
async function media(url:string){const r=await fetch(apiBaseUrl+url,{headers});if(!r.ok)throw Error(`Photo unavailable (${r.status})`);const src=URL.createObjectURL(await r.blob());urls.push(src);return src}
async function apply(p:ServerProfile){const slots=Array(8).fill(null) as (Photo|null)[];for(const a of p.avatars)slots[a.position]={id:a.mediaId,src:await media(a.url),position:a.position};const archive:Photo[]=[];for(const a of p.recentlyRemoved||[])archive.push({id:a.mediaId,src:await media(a.url),position:a.position});profile.value={...initial,name:p.displayName,age:p.age??'',city:p.city??'',zodiac:p.zodiac??'',bio:p.bio,slots,archive,selected:p.avatars.find(a=>a.url===p.avatar)?.mediaId||''}}
const stats=ref({followingCount:0,followersCount:0,likesCount:0,postLikesCount:0,imageCardLikesCount:0,visits:[] as {visitorId:string;profileId:string}[],letters:[] as {content:string}[]})
const settingsOpen=ref(false),privacyOpen=ref(false)
const draft=ref({...profile.value}),view=ref(props.person?'public':'profile'),sheet=ref(''),error=ref(''),notice=ref(''),kind=ref('Following'),outgoing=ref(false),remove=ref(-1),zoom=ref(1),canvas=ref<HTMLCanvasElement>(),file=ref<HTMLInputElement>(),image=ref<HTMLImageElement>(),followed=ref(!!props.person?.following),busy=ref(false),largePhoto=ref('')
const own=computed(()=>profile.value.slots.find(p=>p?.id===profile.value.selected)?.src||asset('05-avatars/avatar-placeholder'))
const photo=computed(()=>publicAvatar.value||asset('05-avatars/avatar-placeholder'))
type Connection={id:string;peerId?:string;displayName:string;avatar?:string;status:string;following?:boolean}
const followers=ref<Connection[]>([]),connections=ref<Connection[]>([]),letters=ref<string[]>([]),selectedPerson=ref<Connection>(),selectedChat=ref<Connection>(),loading=ref(false)
const following=computed(()=>connections.value.filter(c=>c.following))
const visits=ref<Connection[]>([]),incoming=ref<Connection[]>([])
async function load(){loading.value=true;try{if(props.person){const p=await api<ServerProfile>(`/profiles/${props.person.peerId||props.person.id}`,{headers});publicProfile.value=p;publicAvatar.value=p.avatar?await media(p.avatar):'';followed.value=p.following;const cards=await api<{items:{url:string}[]}>(`/profiles/${p.id}/image-cards`,{headers});publicCards.value=await Promise.all(cards.items.map(c=>media(c.url)));const posts=await api<{items:{id:string;content:string;attachments:{url:string;kind:string}[]}[]}>(`/posts?userId=${p.id}&limit=100&offset=0`,{headers});publicMoments.value=await Promise.all(posts.items.map(async m=>({id:m.id,text:m.content,src:m.attachments.find(a=>a.kind==='image')?await media(m.attachments.find(a=>a.kind==='image')!.url):''})));return}const p=await api<ServerProfile>('/profiles/me',{headers});await apply(p);stats.value=await api('/profiles/me/stats',{headers});letters.value=stats.value.letters.map(l=>l.content);const all:Connection[]=[];for(let offset=0;;offset+=100){const r=await api<{items:Connection[];hasMore?:boolean}>(`/conversations?tab=messages&hidden=false&limit=100&offset=${offset}`,{headers});all.push(...r.items);if(!r.hasMore)break}connections.value=all;const fans:Connection[]=[];for(let offset=0;;offset+=100){const r=await api<{items:{id:string;displayName:string}[]}>(`/profiles/me/followers?limit=100&offset=${offset}`,{headers});fans.push(...r.items.map(f=>{const c=all.find(c=>c.peerId===f.id);return {id:c?.id||f.id,peerId:f.id,displayName:f.displayName,status:c?.status||'waiting'}}));if(r.items.length<100)break}followers.value=fans;visits.value=[];incoming.value=[];for(const v of stats.value.visits){const id=v.visitorId===p.id?v.profileId:v.visitorId;const other=await api<Pick<ServerProfile,'id'|'displayName'>>(`/profiles/${id}/summary`,{headers});const connection=all.find(c=>c.peerId===other.id);const c={id:connection?.id||other.id,peerId:other.id,displayName:other.displayName,status:connection?.status||'waiting'};(v.visitorId===p.id?visits.value:incoming.value).push(c)}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>void load())
const title=computed(()=>view.value==='edit'?'Edit profile':view.value==='public'?'Profile':view.value==='connections'?kind.value:view.value==='visitors'?'Visitors':view.value==='letters'?'My letters':'My little corner')
function back(){error.value='';if(sheet.value){sheet.value=['archive','remove','crop'].includes(sheet.value)?'gallery':'';return}if(['profile','public'].includes(view.value))emit('close');else view.value='profile'}
function edit(){draft.value={...profile.value};view.value='edit';error.value=''}
async function save(){const age=Number(draft.value.age);if(!draft.value.name.trim()||!Number.isInteger(age)||age<18||age>100){error.value='Enter a name and an age between 18 and 100.';return}busy.value=true;error.value='';try{await apply(await api<ServerProfile>('/profiles/me',{method:'PATCH',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({displayName:draft.value.name.trim(),age,city:draft.value.city.trim(),...(draft.value.zodiac?{zodiac:draft.value.zodiac}:{}),bio:draft.value.bio})}));view.value='profile';notice.value='Profile saved.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function avatarAction(action:string,mediaId:string){busy.value=true;error.value='';try{await apply(await post<ServerProfile>('/profiles/me/avatars',{action,mediaId,...(action==='remove'?{confirm:true}:{})},props.token));sheet.value=action==='select'?'':'gallery'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function removePhoto(){void avatarAction('remove',profile.value.slots[remove.value]!.id)}
function restore(i:number){void avatarAction('restore',profile.value.archive[i]!.id)}
function pick(){file.value!.value='';file.value!.click()}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const img=new Image();const url=URL.createObjectURL(f);img.onload=async()=>{image.value=img;zoom.value=1;sheet.value='crop';await nextTick();draw();URL.revokeObjectURL(url)};img.onerror=()=>{error.value='This photo could not be opened.';URL.revokeObjectURL(url)};img.src=url}
function draw(){const c=canvas.value!,img=image.value!,scale=Math.max(c.width/img.width,c.height/img.height)*zoom.value;c.getContext('2d')!.drawImage(img,(c.width-img.width*scale)/2,(c.height-img.height*scale)/2,img.width*scale,img.height*scale)}
async function saveAvatar(){busy.value=true;error.value='';try{const blob=await new Promise<Blob>(resolve=>canvas.value!.toBlob(b=>resolve(b!),'image/jpeg',.85));const uploaded=await api<{id:string}>('/media/uploads?purpose=avatar&filename=avatar.jpg',{method:'POST',headers:{...headers,'Content-Type':'image/jpeg'},body:blob});await post('/profiles/me/avatars',{action:'add',mediaId:uploaded.id},props.token);await apply(await post<ServerProfile>('/profiles/me/avatars',{action:'select',mediaId:uploaded.id},props.token));sheet.value='';notice.value='Avatar saved.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function follow(){if(!props.person||(!publicProfile.value?.permissions.canFollow||props.person.status!=='open')||busy.value)return;busy.value=true;error.value='';try{await api(`/conversations/${props.person.id}`,{method:'PATCH',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'},body:JSON.stringify({following:!followed.value})});followed.value=!followed.value}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
<Transition name="push"><SettingsFlow @security="emit('security')" :token="token" :privacy="privacyOpen" v-if="settingsOpen" @close="settingsOpen=false" /></Transition>
<ProfileFlow v-if="selectedPerson" :token="token" :person="selectedPerson" @close="selectedPerson=undefined;load()" @chat="selectedChat=selectedPerson;selectedPerson=undefined" @safety="selectedChat=selectedPerson;selectedPerson=undefined" />
<ChatFlow v-if="selectedChat" :token="token" :conversation="selectedChat" @close="selectedChat=undefined;load()" @collect="selectedChat=undefined;notice='Collect your reply from Messages to continue.'" />
<section v-show="!selectedPerson&&!selectedChat" class="d4-profile" :class="{'person-page':person,'profile-page':!person}" @keydown.esc="person && $event.stopPropagation();back()" @keydown.esc.capture="if (!person && ['likes','gallery','archive','remove','crop'].includes(sheet)) { $event.stopPropagation(); back() }">
<header :class="{'person-header':person,'ui-header':!person}"><button :class="{'ui-icon-button ui-icon-button--person-header':person,'ui-icon-button ui-icon-button--profile-header':!person}" id="page-back" :aria-label="tr('Back')" @click="back"><img :src="asset('08-interface-icons/icon-chevron-left-light-22')" width="22" height="22" alt=""></button><h1 v-if="!person">{{tr(view==='connections'?'Connections':title)}}</h1><button v-if="person" class="ui-icon-button ui-icon-button--person-header" id="public-more" :aria-label="tr('Profile options')" @click="sheet='safety'">•••</button><button v-else class="ui-icon-button ui-icon-button--profile-header" id="open-settings" :aria-label="t('settings')" @click="privacyOpen=false;settingsOpen=true"><img :src="asset('08-interface-icons/icon-settings-light-24')" width="24" height="24" alt=""></button></header>
<p v-if="error" role="alert" class="d4-error">{{tr(error)}}</p><p v-if="notice" role="status" class="d4-note">{{tr(notice)}}</p>
<div class="d4-body" :class="`profile-view-${view}`" :key="view">
<template v-if="view==='profile'"><div class="profile-hero"><button id="edit-avatar" :aria-label="tr('Change avatar')" @click="sheet='gallery'"><img class="profile-avatar-image" :src="own" :alt="tr('Your avatar')"><span class="profile-camera"><img class="profile-camera-icon" :src="asset('08-interface-icons/icon-camera-dark-15')" alt=""></span></button><button id="edit-profile" @click="edit"><strong class="profile-name-text">{{profile.name}}</strong></button><p class="profile-meta">{{profile.age}} · {{profile.zodiac?profile.zodiac+' · ':''}}{{profile.city}}</p><p class="profile-bio">{{profile.bio}}</p></div><div class="profile-counters"><button class="profile-count" id="following" @click="kind='Following';view='connections'">{{stats.followingCount}}<small class="profile-count-label">{{tr("Following")}}</small></button><button class="profile-count" id="followers" @click="kind='Followers';view='connections'">{{stats.followersCount}}<small class="profile-count-label">{{tr("Followers")}}</small></button><button class="profile-count" id="likes" @click="sheet='likes'">{{stats.likesCount}}<small class="profile-count-label">{{tr("Likes")}}</small></button><button id="profile-visitors" @click="view='visitors'">◷<small class="profile-count-label">{{tr("Visitors ›")}}</small></button></div><MomentsFlow :token="token"><template #visibility><button id="profile-global-visibility" class="d4-row ui-row ui-row--profile" @click="privacyOpen=true;settingsOpen=true">{{tr('Profile visibility')}} <span class="profile-row-chevron">›</span></button></template></MomentsFlow><button id="profile-letters" class="d4-row ui-row ui-row--profile" @click="view='letters'">{{tr("My letters")}} <span class="profile-row-chevron">›</span></button></template>
<template v-else-if="view==='edit'"><form @submit.prevent="save" novalidate><label class="profile-edit-label">{{tr("Nickname")}}<input class="ui-input ui-input--profile" id="edit-name" v-model="draft.name" maxlength="24"></label><label class="profile-edit-label">{{tr("Age")}}<input class="ui-input ui-input--profile" id="edit-age" v-model="draft.age" type="number" min="18" max="100" :aria-invalid="!!error"></label><label class="profile-edit-label">{{tr("City")}}<input class="ui-input ui-input--profile" id="edit-city" v-model="draft.city" maxlength="40"></label><label class="profile-edit-label">{{tr("Zodiac")}}<select class="ui-input ui-input--profile" id="edit-zodiac" v-model="draft.zodiac"><option value="" disabled>—</option><option v-for="sign in ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces']" :key="sign" :value="sign">{{tr(sign)}}</option></select></label><label class="profile-edit-label">{{tr("About me")}}<textarea class="ui-input ui-input--profile ui-input--profile-area" id="edit-bio" v-model="draft.bio" maxlength="200"></textarea></label><button id="change-avatar" type="button" class="ui-button ui-button--secondary" @click="sheet='gallery'">{{tr("Change avatar")}}</button><button id="save-profile" :disabled="busy||loading" class="primary ui-button">{{tr("Save changes")}}</button></form></template>
<template v-else-if="view==='public'">
<div class="person-hero profile-hero"><button id="public-avatar" class="ui-avatar-button ui-avatar-button--person" :aria-label="tr('View profile photo')" @click="largePhoto=photo;sheet='photo'"><img :src="photo" :alt="publicProfile?.displayName"></button><h2 class="person-name">{{publicProfile?.displayName}}<span v-if="publicProfile&amp;&amp;'gender' in publicProfile&amp;&amp;['female','male'].includes(String(publicProfile.gender))" class="person-gender" :class="{'person-gender-male':publicProfile.gender==='male'}">{{publicProfile.gender==='female'?'♀':'♂'}}</span></h2><p v-if="[publicProfile?.age,publicProfile?.zodiac,publicProfile?.city].filter(Boolean).length" class="person-meta">{{[publicProfile?.age,publicProfile?.zodiac,publicProfile?.city].filter(Boolean).join(' · ')}}</p><p v-if="publicProfile?.bio" class="person-bio">{{publicProfile?.bio}}</p></div>
<div class="person-cards d4-cards"><button v-for="src in publicCards" :key="src" class="ui-person-card" @click="largePhoto=src;sheet='photo'"><img :src="src" :alt="tr('Image card')"></button></div>
<h2 class="person-moments-title">{{tr("Moments")}}</h2><article v-for="m in publicMoments" :key="m.id" class="person-moment d4-moment"><p class="person-moment-text">{{m.text}}</p><button v-if="m.src" class="ui-person-moment-photo" @click="largePhoto=m.src;sheet='photo'"><img :src="m.src" :alt="tr('Moment photo')"></button></article><p v-if="!publicMoments.length" class="person-empty d4-empty">{{tr("No moments yet.")}}</p><p v-if="person!.status!=='open'" class="person-unlock">{{tr("Following unlocks after they reply.")}}</p>
</template>
<template v-else-if="view==='connections'"><div class="ui-profile-tabs"><button :aria-pressed="kind==='Following'" @click="kind='Following'">{{tr('Following')}}</button><button :aria-pressed="kind==='Followers'" @click="kind='Followers'">{{tr('Followers')}}</button></div><button v-for="c in kind==='Following'?following:followers" :key="c.id" class="d4-row ui-row ui-row--profile-connection" :data-connection="c.id" @click="selectedPerson=c"><img class="profile-list-avatar" :src="c.avatar||asset('05-avatars/avatar-placeholder')" alt=""><strong>{{c.displayName}}</strong><span class="profile-row-chevron">›</span></button><div v-if="kind==='Followers'?!followers.length:!following.length" class="profile-empty"><img class="profile-empty-image" :src="asset('02-bird-static/female-4')" alt=""><h3 class="profile-empty-title">{{tr('Your circle is just beginning.')}}</h3><p class="profile-empty-copy">{{tr('Every connection starts with a little hello.')}}</p><small class="profile-empty-status">{{tr(kind==='Following'?'No following yet.':'No followers yet.')}}</small></div></template>
<template v-else-if="view==='visitors'"><div class="d4-tabs ui-profile-tabs"><button :aria-pressed="!outgoing" @click="outgoing=false">{{tr("Visited me")}}</button><button :aria-pressed="outgoing" @click="outgoing=true">{{tr("I visited")}}</button></div><button v-for="c in outgoing?visits:incoming" :key="c.id" class="d4-row ui-row ui-row--profile-visitor" @click="selectedPerson=c"><img class="profile-list-avatar" :src="c.avatar||asset('05-avatars/avatar-placeholder')" alt=""><strong>{{c.displayName}}</strong><span class="profile-row-chevron">›</span></button><div v-if="!(outgoing?visits:incoming).length" class="profile-empty"><img class="profile-empty-image" :src="asset('02-bird-static/female-4')" alt=""><h3 class="profile-empty-title">{{tr('No visits yet.')}}</h3><p class="profile-empty-copy">{{tr('Every connection starts with a little hello.')}}</p><small class="profile-empty-status">{{tr(outgoing?'No visits yet.':'No visitors yet.')}}</small></div></template>
<template v-else><p v-if="loading">{{tr("Loading letters…")}}</p><div v-else-if="!letters.length" class="profile-empty profile-empty-letters"><img class="profile-empty-image" :src="asset('02-bird-static/female-4')" alt=""><h3 class="profile-empty-title">{{tr('Nothing here yet.')}}</h3><p class="profile-empty-copy">{{tr('Every connection starts with a little hello.')}}</p><small class="profile-empty-status">{{tr('No letters yet.')}}</small></div><article v-for="(letter,i) in letters" :key="i" class="d4-moment profile-letter"><small class="profile-letter-label">{{tr('A letter I sent')}}</small><p class="profile-letter-text">{{letter}}</p></article></template>
</div>
<div v-if="view==='public'" class="person-actions d4-public-actions"><button id="public-follow" class="ui-button ui-button--person-follow" :disabled="!publicProfile?.permissions.canFollow||person!.status!=='open'||busy" @click="follow">{{tr(followed?'✓ Following':'＋ Follow')}}</button><button id="public-chat" class="ui-button ui-button--person-chat" @click="emit('chat')">{{tr("Chat")}}</button></div>
<nav v-if="view==='profile'&&!person&&!settingsOpen&&!selectedPerson&&!selectedChat" class="main-nav" :aria-label="tr('Main navigation')"><button class="main-nav__item" type="button" :aria-label="tr('Home')" @click="emit('close')"><img :src="asset('09-navigation-system/tab-discover-inactive')" alt="">{{tr("Home")}}</button><button class="main-nav__item" type="button" :aria-label="tr('Messages')" @click="emit('inbox')"><img :src="asset('09-navigation-system/tab-messages-inactive')" alt="">{{tr("Messages")}}</button><button class="main-nav__item" type="button" :aria-label="tr('Profile')" aria-current="page"><img :src="asset('09-navigation-system/tab-profile-active')" alt="">{{tr("Profile")}}</button></nav>
<input ref="file" type="file" accept="image/*" style="display:none" @change="upload">
<Transition name="d4-sheet"><div v-if="sheet" class="d4-veil" :class="{'person-veil ui-scrim':person,'ui-scrim':!person}" @click.self="back"><section role="dialog" aria-modal="true" :aria-label="tr(sheet==='gallery'?'Avatar':sheet==='archive'?'Recently removed':sheet==='remove'?'Remove photo':sheet==='crop'?'Crop avatar':sheet==='photo'?'Profile photo':sheet==='likes'?'Likes':'Report or block')" class="d4-sheet" :class="{'person-sheet ui-sheet':person,'person-photo-sheet':person&&sheet==='photo','person-safety-sheet':person&&sheet==='safety','profile-likes ui-dialog ui-dialog--profile-likes':!person&&sheet==='likes','ui-sheet ui-sheet--profile-avatar avatar-panel':!person&&!['likes','remove'].includes(sheet),'ui-dialog ui-dialog--avatar avatar-confirm':!person&&sheet==='remove',[`avatar-panel-${sheet}`]:!person&&sheet!=='likes','avatar-panel-removed':!person&&sheet==='gallery'&&profile.archive.length>0}"><span v-if="person||!['likes','remove'].includes(sheet)" class="ui-sheet__grabber" :class="{'avatar-grabber':!person}"></span><button class="d4-close" :class="{'person-close ui-icon-button ui-icon-button--safety-close':person,'ui-icon-button ui-icon-button--reply-close':!person,'avatar-panel-close':!person&&!['likes','remove'].includes(sheet),'avatar-confirm-close':!person&&sheet==='remove'}" :aria-label="tr('Close')" @click="back">×</button>
<template v-if="sheet==='gallery'"><h2 class="avatar-title">{{tr("Choose an avatar")}}</h2><div class="avatar-gallery"><div v-for="(p,i) in profile.slots" :key="i" class="avatar-slot"><template v-if="p"><button class="avatar-option" :data-avatar-slot="i" :aria-pressed="profile.selected===p.id" @click="avatarAction('select',p.id)"><img class="avatar-thumbnail" :src="p.src" :alt="tr(`Avatar ${i+1}`)"><span class="avatar-selected" v-if="profile.selected===p.id">✓</span></button><button class="avatar-remove" :data-remove-avatar="i" :aria-label="tr(`Remove photo ${i+1}`)" @click="remove=i;sheet='remove'">×</button></template><button v-else class="avatar-empty" :data-upload-avatar="i" :aria-label="tr(`Upload a photo ${i+1}`)" @click="pick()"><img class="avatar-empty-icon" :src="asset('08-interface-icons/icon-camera-muted-24')" alt=""><small class="avatar-empty-label">{{tr("Not uploaded")}}</small></button></div></div><button id="upload-avatar" class="ui-button" :disabled="profile.slots.every(Boolean)" @click="pick()">{{tr("Upload a photo")}}</button><button v-if="profile.archive.length" id="removed-avatars" class="ui-button ui-button--text" @click="sheet='archive'">{{tr("Recently removed (")}}{{profile.archive.length}})</button></template>
<template v-else-if="sheet==='remove'"><h2 class="avatar-confirm-title">{{tr("Remove this photo?")}}</h2><p class="avatar-confirm-copy">{{tr("You can restore removed photos from Recently removed.")}}</p><button id="confirm-remove-avatar" class="ui-button" @click="removePhoto">{{tr("Remove photo")}}</button><button class="ui-button ui-button--text avatar-cancel" @click="sheet='gallery'">{{tr("Cancel")}}</button></template>
<template v-else-if="sheet==='archive'"><h2 class="avatar-title">{{tr("Recently removed")}}</h2><p class="avatar-archive-copy">{{tr("Restore a photo to an empty position.")}}</p><div class="avatar-gallery avatar-archive-grid"><button v-for="(p,i) in profile.archive" :key="p.id" class="avatar-option" :data-restore-avatar="i" :aria-label="tr(`Restore ${i+1}`)" @click="restore(i)"><img class="avatar-thumbnail" :src="p.src" :alt="tr('Removed avatar')"></button></div><button id="avatar-gallery-back" class="ui-button ui-button--secondary" @click="sheet='gallery'">{{tr("Back")}}</button></template>
<template v-else-if="sheet==='crop'"><h2 class="avatar-title">{{tr("Crop avatar")}}</h2><div class="avatar-crop-window"><canvas id="avatar-canvas" ref="canvas" width="320" height="320"></canvas></div><label class="avatar-zoom-label">{{tr("Zoom")}}<input id="avatar-zoom" class="ui-avatar-range" v-model="zoom" type="range" min="1" max="3" step=".01" @input="draw"></label><button id="save-avatar" :disabled="busy" class="ui-button" @click="saveAvatar">{{tr("Use photo")}}</button></template>
<template v-else-if="sheet==='photo'"><h2 v-if="person" class="person-sheet-title">{{tr("Photo")}}</h2><img class="d4-photo" :class="{'person-photo':person,'avatar-large-photo':!person}" :src="largePhoto" :alt="tr('Profile photo')"></template>
<template v-else-if="sheet==='likes'"><h2 class="profile-likes-title">{{tr("Likes")}}</h2><p class="profile-likes-total profile-likes-row">{{tr("Likes")}} <strong class="profile-likes-value">{{stats.likesCount}}</strong></p><p class="profile-likes-row" data-likes="posts">{{tr("Moments")}} <strong class="profile-likes-value">{{stats.postLikesCount}}</strong></p><p class="profile-likes-row" data-likes="cards">{{tr("Image cards")}} <strong class="profile-likes-value">{{stats.imageCardLikesCount}}</strong></p><button class="primary ui-button profile-likes-button" @click="sheet=''">{{tr("Got it")}}</button></template>
<template v-else-if="sheet==='safety'"><h2 class="person-sheet-title">{{tr("Report or block")}}</h2><p class="person-safety-description">{{tr("Choose how you would like to manage this person.")}}</p><button id="safety-report" class="ui-safety-option ui-safety-option--person person-safety-option" @click="emit('safety','report')"><img :src="asset('08-interface-icons/icon-flag-light-22')" alt=""><span>{{tr("Report")}}<small class="person-option-description">{{tr("Tell us about inappropriate content")}}</small></span></button><button id="safety-block" class="ui-safety-option ui-safety-option--person person-safety-option" @click="emit('safety','block')"><span class="person-block-symbol">⊘</span><span>{{tr("Block")}}<small class="person-option-description">{{tr("Stop contact from this person")}}</small></span></button></template>
</section></div></Transition>
</section>
</template>
<style scoped src="../styles/pages/person.css"></style>
<style scoped src="../styles/pages/profile.css"></style>
